const input = $input.first().json;
const body = input.body || input;
const sub = body.subscription || {};
const billing = body.billing || {};
const method = body.method || {};
const extractEmail = (value) => {
  const match = String(value || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return match ? match[0].toLowerCase() : null;
};

const errors = [];
if (!body.userId) errors.push('userId is required');
if (!sub.id) errors.push('subscription.id is required');
if (!sub.name) errors.push('subscription.name is required');
if (!body.userEmail) errors.push('userEmail is required');

const targetEmail = sub.supportEmail || body.targetEmail || extractEmail(sub.sourceFrom) || null;
const copyEmail = body.userEmail || null;
const amount = Number.parseFloat(sub.amount) || 0;
const currency = body.currency || sub.currency || 'EUR';
const cycle = sub.cycle || 'monthly';
const cycleMultiplier = { weekly: 52 / 12, monthly: 1, quarterly: 1 / 3, annual: 1 / 12 };
const monthlyAmount = amount * (cycleMultiplier[cycle] || 1);
const annualSavings = monthlyAmount * 12;
const now = new Date();
const formatDate = (value) => {
  if (!value) return 'Non defini';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Non defini';
  return date.toLocaleDateString('fr-FR', { day: '2-digit', month: 'long', year: 'numeric' });
};
let daysUntilCharge = billing.daysUntilCharge;
if ((daysUntilCharge === undefined || daysUntilCharge === null) && billing.nextChargeDate) {
  const next = new Date(billing.nextChargeDate);
  if (!Number.isNaN(next.getTime())) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    next.setHours(0, 0, 0, 0);
    daysUntilCharge = Math.ceil((next - today) / 86400000);
  }
}
const methodKey = method.key || body.methodKey || (body.cancellationType === 'email' || body.cancellationType === 'lre' ? 'email_letter' : 'direct');
const methodTitle = method.title || body.methodTitle || (body.cancellationType === 'lre' ? 'Lettre recommandee electronique' : 'Email de resiliation');
const isUrgent = typeof daysUntilCharge === 'number' && daysUntilCharge <= 3;
const urgencyLabel = typeof daysUntilCharge !== 'number'
  ? 'OK'
  : daysUntilCharge <= 0 ? 'AUJOURD HUI'
  : daysUntilCharge <= 3 ? 'URGENT'
  : daysUntilCharge <= 7 ? 'BIENTOT'
  : 'OK';

return [{ json: {
  ok: errors.length === 0,
  statusCode: errors.length ? 400 : 200,
  errors,
  event: body.event || 'cancellation_request',
  requestedAt: body.requestedAt || body.timestamp || now.toISOString(),
  userId: body.userId || null,
  userEmail: body.userEmail || null,
  targetEmail,
  copyEmail,
  userName: body.userName || 'Client Trimly',
  userAddress: body.userAddress || {},
  callbackUrl: body.callbackUrl || null,
  cancellationType: body.cancellationType || 'email',
  subId: sub.id || null,
  subName: sub.name || 'Abonnement',
  subAmount: amount,
  subCycle: cycle,
  subCategory: sub.category || 'Autre',
  subProvider: sub.provider || null,
  sourceFrom: sub.sourceFrom || null,
  sourceEmail: sub.sourceEmail || null,
  currency,
  monthlyAmount: monthlyAmount.toFixed(2),
  annualSavings: annualSavings.toFixed(2),
  nextChargeDate: formatDate(billing.nextChargeDate || sub.nextChargeDate),
  rawNextChargeDate: billing.nextChargeDate || sub.nextChargeDate || null,
  daysUntilCharge: daysUntilCharge ?? null,
  methodKey,
  methodTitle,
  methodDescription: method.description || '',
  originalMessage: body.message || body.letterContent || '',
  isUrgent,
  urgencyLabel,
  today: formatDate(now)
} }];

const d = $input.first().json;
const escapeHtml = (value) => String(value || '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const cycleLabel = { weekly: 'hebdomadaire', monthly: 'mensuel', quarterly: 'trimestriel', annual: 'annuel' }[d.subCycle] || 'mensuel';

function formalLetter() {
  return `${d.userName}
${d.userEmail}

Le ${d.today}

Objet : Demande de resiliation - ${d.subName}

Madame, Monsieur,

Je vous informe par la presente de ma decision de resilier mon abonnement ${d.subName} a compter de la reception de cette demande.

Details de mon abonnement :
- Service : ${d.subName}
- Montant : ${d.subAmount} ${d.currency} (${cycleLabel})
- Prochaine echeance estimee : ${d.nextChargeDate}

Je vous demande de cesser tout prelevement automatique futur et de me confirmer par ecrit la date effective de resiliation.

Je conserve une copie de cette demande comme preuve.

Cordialement,

${d.userName}`;
}

function phoneScript() {
  return `SCRIPT DE RESILIATION - ${d.subName.toUpperCase()}

Bonjour, je souhaite resilier mon abonnement ${d.subName}.

Informations a donner :
- Nom : ${d.userName}
- Email du compte : ${d.userEmail}
- Montant actuel : ${d.subAmount} ${d.currency} (${cycleLabel})

Phrase principale :
Je souhaite que vous annuliez mon abonnement et que vous cessiez tout prelevement automatique a partir d'aujourd'hui.

Si on propose une reduction :
Je comprends votre offre, mais ma decision est prise. Je souhaite resilier definitivement.

Confirmation a demander :
Pouvez-vous m'envoyer une confirmation ecrite par email avec un numero de dossier ?

A noter :
- Nom de l'agent :
- Numero de dossier :
- Date effective :
- Dernier prelevement :`;
}

function bankNote() {
  return `DOSSIER BANCAIRE - ${d.subName.toUpperCase()}

Marchand : ${d.subName}
Montant habituel : ${d.subAmount} ${d.currency} (${cycleLabel})
Prochain debit estime : ${d.nextChargeDate}

Action demandee : revoquer l'autorisation de prelevement recurrent et contester tout debit posterieur a ma demande de resiliation.

Preuves a joindre :
- Demande de resiliation envoyee au service
- Captures d'ecran du compte ou du chat
- Releves bancaires montrant les debits
- Reponse ou absence de reponse du service

Important : cette demarche ne remplace pas la resiliation contractuelle chez le service.`;
}

function directGuide() {
  return d.originalMessage || `Connectez-vous au site officiel de ${d.subName}, ouvrez Compte / Billing / Abonnement, puis choisissez Cancel, Resilier ou Turn off auto-renew. Gardez une preuve de confirmation.`;
}

const contentByMethod = {
  email_letter: formalLetter,
  phone_chat: phoneScript,
  bank_stop: bankNote,
  direct: directGuide,
};
const letter = (contentByMethod[d.methodKey] || directGuide)();
const titleByMethod = {
  email_letter: `Lettre de resiliation - ${d.subName}`,
  phone_chat: `Script de resiliation - ${d.subName}`,
  bank_stop: `Dossier bancaire - ${d.subName}`,
  direct: `Guide de resiliation - ${d.subName}`,
};
const emailSubject = `${d.isUrgent ? 'URGENT - ' : ''}${titleByMethod[d.methodKey] || titleByMethod.direct}`;
const alertBlock = d.isUrgent
  ? `<div style="background:#FEF2F2;border-left:4px solid #DC2626;padding:12px;border-radius:6px;margin-bottom:16px;"><strong>Urgent :</strong> prochaine echeance ${escapeHtml(d.nextChargeDate)}.</div>`
  : `<div style="background:#F0FDF4;border-left:4px solid #16A34A;padding:12px;border-radius:6px;margin-bottom:16px;"><strong>Suivi :</strong> conservez une preuve et attendez la confirmation officielle.</div>`;
const htmlLetter = `<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;color:#0F172A;"><div style="background:#0F172A;color:white;padding:20px;border-radius:10px 10px 0 0;"><h2 style="margin:0;font-size:20px;">${escapeHtml(titleByMethod[d.methodKey] || titleByMethod.direct)}</h2><p style="margin:6px 0 0;opacity:.75;">Genere par Trimly le ${escapeHtml(d.today)}</p></div><div style="border:1px solid #E2E8F0;border-top:none;padding:22px;border-radius:0 0 10px 10px;">${alertBlock}<pre style="background:#F8FAFC;padding:18px;border-radius:8px;white-space:pre-wrap;font-family:Arial,sans-serif;line-height:1.6;">${escapeHtml(letter)}</pre><p style="font-size:12px;color:#64748B;text-align:center;margin-top:18px;">Economie potentielle : <strong>${escapeHtml(d.annualSavings)} ${escapeHtml(d.currency)}/an</strong></p></div></div>`;
const reminders = [
  { type: 'followup_48h', triggerAt: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(), message: `Avez-vous recu la confirmation de resiliation de ${d.subName} ?` },
  { type: 'check_5d', triggerAt: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString(), message: `Verifiez que ${d.subName} ne vous a pas debite apres la demande.` },
];
if (typeof d.daysUntilCharge === 'number' && d.daysUntilCharge > 3) {
  reminders.push({ type: 'before_charge', triggerAt: new Date(Date.now() + Math.max(d.daysUntilCharge - 2, 1) * 24 * 60 * 60 * 1000).toISOString(), message: `Confirmez la resiliation de ${d.subName} avant la prochaine echeance.` });
}

return [{ json: { ...d, letter, htmlLetter, emailSubject, messageType: d.methodKey, reminders, totalReminders: reminders.length } }];
